+fn retain_overlay_buffers<T>(
+    entries: &mut Vec<T>,
+    age: impl Fn(&T) -> u64,
+    size: impl Fn(&T) -> usize,
+) {
+    entries.sort_by_key(|entry| std::cmp::Reverse(age(entry)));
+    let mut bytes = 0;
+    let mut count = 0;
+    entries.retain(|entry| {
+        let next = bytes + size(entry);
+        if count >= MAX_OVERLAY_BUFFERS || next > MAX_OVERLAY_TEXT_BYTES {
+            return false;
+        }
+        bytes = next;
+        count += 1;
+        true
+    });
+}
